                  "radius": 4,
                  "height": {
                    "$document": "/dimensions/postHeight"
                  }
                }
              }
            ],
            "components": [
              {
                "id": "base",
                "part": "plate",
                "position": [
                  10,
                  20,
                  0
                ],
                "rotation": 30
              },
              {
                "id": "postLeft",
                "part": "post",
                "position": [
                  80,
                  60,
                  30
                ]
              },
              {
                "id": "postRight",
                "part": "post",
                "position": [
                  -40,
